//! Status-change webhooks.
//!
//! When a credential's status flips ([`crate::status::revoke_credential`]),
//! [`Notifier::notify`] sends the change to the relying parties that
//! subscribed to the issuing tenant's changes. A subscription is a tenant
//! setting of kind [`WEBHOOK_KIND`] whose value holds the endpoint `url`.
//!
//! The canary is a platform subscription that receives every change;
//! [`Notifier::canary_healthy`] is the notifier's health check. Every
//! delivery attempt is reported to the [`DeliverySink`].

use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};
use std::time::Duration;

use serde_json::json;

use crate::settings::{Setting, SettingsStore};
use crate::status::StatusChange;
use crate::webhook::WebhookTransport;

/// How long one status change may take to fan out.
pub const DISPATCH_BUDGET: Duration = Duration::from_secs(10);

/// Setting kind of a webhook subscription.
pub const WEBHOOK_KIND: &str = "webhook";

pub const CANARY_ID: &str = "canary";
pub const CANARY_URL: &str = "https://example.com/webhooks/status";

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Subscription {
    pub id: String,
    pub url: String,
}

impl Subscription {
    pub fn canary() -> Self {
        Subscription { id: CANARY_ID.to_string(), url: CANARY_URL.to_string() }
    }

    /// The subscription a webhook setting describes; its id is the part of
    /// the key after `webhook/`.
    pub fn from_setting(setting: &Setting) -> Option<Self> {
        let url = setting.value.get("url")?.as_str()?;
        let id = setting.key.strip_prefix("webhook/").unwrap_or(&setting.key);
        Some(Subscription { id: id.to_string(), url: url.to_string() })
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Outcome {
    /// The endpoint acknowledged the call (2xx).
    Delivered { status: u16 },
    /// The endpoint refused the call or could not be reached.
    Failed { reason: String },
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DeliveryEvent {
    pub tenant: String,
    pub subscription: String,
    pub outcome: Outcome,
}

/// Where delivery outcomes go (metrics, audit).
pub trait DeliverySink: Send + Sync {
    fn record(&self, event: DeliveryEvent);
}

/// Keeps every event in memory.
#[derive(Debug, Default)]
pub struct MemorySink {
    events: Mutex<Vec<DeliveryEvent>>,
}

impl MemorySink {
    pub fn events(&self) -> Vec<DeliveryEvent> {
        self.events.lock().unwrap().clone()
    }
}

impl DeliverySink for MemorySink {
    fn record(&self, event: DeliveryEvent) {
        self.events.lock().unwrap().push(event);
    }
}

/// The JSON body sent for `change`.
pub fn payload(change: &StatusChange) -> Vec<u8> {
    json!({
        "type": "credential.status_changed",
        "credential_id": change.credential_id,
        "issuer": change.issuer,
        "status_list": change.status_list,
        "status_index": change.status_index,
        "revoked": change.revoked,
    })
    .to_string()
    .into_bytes()
}

pub struct Notifier {
    settings: Arc<SettingsStore>,
    transport: Arc<dyn WebhookTransport>,
    sink: Arc<dyn DeliverySink>,
    /// Subscribers to every tenant's changes.
    platform: Vec<Subscription>,
    canary_ok: AtomicBool,
}

impl Notifier {
    pub fn new(settings: Arc<SettingsStore>, transport: Arc<dyn WebhookTransport>, sink: Arc<dyn DeliverySink>) -> Self {
        Notifier {
            settings,
            transport,
            sink,
            platform: vec![Subscription::canary()],
            canary_ok: AtomicBool::new(false),
        }
    }

    /// Adds a subscriber to every tenant's changes.
    pub fn with_platform_subscriber(mut self, subscription: Subscription) -> Self {
        self.platform.push(subscription);
        self
    }

    /// Whether the canary acknowledged the most recent change.
    pub fn canary_healthy(&self) -> bool {
        self.canary_ok.load(Ordering::SeqCst)
    }

    /// Sends `change` to the platform subscribers and to every subscriber of
    /// the issuing tenant.
    pub async fn notify(&self, change: &StatusChange) {
        let tenant = change.issuer.as_str();
        let body = payload(change);

        let fan_out = async {
            for sub in &self.platform {
                let delivered = self.dispatch(tenant, sub, &body).await;
                if sub.id == CANARY_ID {
                    self.canary_ok.store(delivered, Ordering::SeqCst);
                }
            }
            for sub in self.subscriptions(tenant).await {
                self.dispatch(tenant, &sub, &body).await;
            }
        };

        if tokio::time::timeout(DISPATCH_BUDGET, fan_out).await.is_err() {
            eprintln!("notifier: {tenant}: fan-out for {} did not finish within {DISPATCH_BUDGET:?}", change.credential_id);
        }
    }

    /// The tenant's webhook subscriptions.
    async fn subscriptions(&self, tenant: &str) -> Vec<Subscription> {
        let mut subscriptions = Vec::new();
        let mut cursor: Option<String> = None;
        loop {
            let page = self.settings.query(tenant, cursor.as_deref()).await;
            subscriptions.extend(page.items.iter().filter(|s| s.kind == WEBHOOK_KIND).filter_map(Subscription::from_setting));
            match page.next {
                Some(next) => cursor = Some(next),
                None => return subscriptions,
            }
        }
    }

    /// POSTs `body` to `sub` and reports the outcome; `true` if delivered.
    async fn dispatch(&self, tenant: &str, sub: &Subscription, body: &[u8]) -> bool {
        let outcome = match self.transport.post(&sub.url, body).await {
            Ok(status) if (200..300).contains(&status) => Outcome::Delivered { status },
            Ok(status) => Outcome::Failed { reason: format!("HTTP {status}") },
            Err(error) => Outcome::Failed { reason: error.to_string() },
        };
        let delivered = matches!(outcome, Outcome::Delivered { .. });
        self.sink.record(DeliveryEvent { tenant: tenant.to_string(), subscription: sub.id.clone(), outcome });
        delivered
    }
}
//! Sending webhook calls.
//!
//! The notifier POSTs through a [`WebhookTransport`], so it runs against a
//! real HTTP client in production and against [`HermeticTransport`] in tests
//! and local runs.

use std::collections::HashMap;
use std::future::Future;
use std::pin::Pin;
use std::sync::Mutex;
use std::time::Duration;

use thiserror::Error;
use url::Url;

use crate::notifier::CANARY_URL;

#[derive(Debug, Clone, Error, PartialEq, Eq)]
pub enum WebhookError {
    #[error("invalid webhook URL {0}")]
    InvalidUrl(String),
    #[error("{0} is unreachable")]
    Unreachable(String),
}

/// The response to one POST: an HTTP status code, or why there was none.
pub type PostFuture<'a> = Pin<Box<dyn Future<Output = Result<u16, WebhookError>> + Send + 'a>>;

/// Something that can POST a JSON body to a webhook URL.
pub trait WebhookTransport: Send + Sync {
    fn post<'a>(&'a self, url: &'a str, body: &'a [u8]) -> PostFuture<'a>;
}

/// How an in-process endpoint answers.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Endpoint {
    /// Answers `status` after `after`.
    Respond { status: u16, after: Duration },
    /// Accepts the connection and never answers.
    Hang,
}

impl Endpoint {
    /// Round trip of a healthy relying-party endpoint.
    pub const TYPICAL_LATENCY: Duration = Duration::from_millis(150);

    pub fn ok() -> Self {
        Endpoint::Respond { status: 200, after: Self::TYPICAL_LATENCY }
    }

    pub fn status(status: u16) -> Self {
        Endpoint::Respond { status, after: Self::TYPICAL_LATENCY }
    }

    pub fn slow(after: Duration) -> Self {
        Endpoint::Respond { status: 200, after }
    }
}

/// Answers every call in-process; nothing leaves the machine. Endpoints are
/// registered per URL (or per host); anything unregistered is unreachable.
/// The canary's host is answered by a local stub that acknowledges every
/// call.
#[derive(Debug)]
pub struct HermeticTransport {
    routes: Mutex<HashMap<String, Endpoint>>,
    hosts: Mutex<HashMap<String, Endpoint>>,
    received: Mutex<HashMap<String, Vec<Vec<u8>>>>,
}

impl Default for HermeticTransport {
    fn default() -> Self {
        HermeticTransport::new()
    }
}

impl HermeticTransport {
    pub fn new() -> Self {
        let transport = HermeticTransport {
            routes: Mutex::new(HashMap::new()),
            hosts: Mutex::new(HashMap::new()),
            received: Mutex::new(HashMap::new()),
        };
        let canary_host = Url::parse(CANARY_URL).ok().and_then(|u| u.host_str().map(str::to_string));
        if let Some(host) = canary_host {
            transport.route_host(&host, Endpoint::Respond { status: 200, after: Duration::ZERO });
        }
        transport
    }

    /// Answers calls to exactly `url` as `endpoint`.
    pub fn route(&self, url: &str, endpoint: Endpoint) {
        self.routes.lock().unwrap().insert(url.to_string(), endpoint);
    }

    /// Answers calls to any URL on `host` as `endpoint`.
    pub fn route_host(&self, host: &str, endpoint: Endpoint) {
        self.hosts.lock().unwrap().insert(host.to_string(), endpoint);
    }

    /// The bodies `url` has answered, in the order they arrived.
    pub fn received(&self, url: &str) -> Vec<Vec<u8>> {
        self.received.lock().unwrap().get(url).cloned().unwrap_or_default()
    }

    fn endpoint_for(&self, url: &str) -> Result<Endpoint, WebhookError> {
        if let Some(endpoint) = self.routes.lock().unwrap().get(url) {
            return Ok(*endpoint);
        }
        let parsed = Url::parse(url).map_err(|_| WebhookError::InvalidUrl(url.to_string()))?;
        let host = parsed.host_str().ok_or_else(|| WebhookError::InvalidUrl(url.to_string()))?;
        self.hosts.lock().unwrap().get(host).copied().ok_or_else(|| WebhookError::Unreachable(url.to_string()))
    }
}

impl WebhookTransport for HermeticTransport {
    fn post<'a>(&'a self, url: &'a str, body: &'a [u8]) -> PostFuture<'a> {
        Box::pin(async move {
            match self.endpoint_for(url)? {
                Endpoint::Hang => std::future::pending().await,
                Endpoint::Respond { status, after } => {
                    tokio::time::sleep(after).await;
                    self.received.lock().unwrap().entry(url.to_string()).or_default().push(body.to_vec());
                    Ok(status)
                }
            }
        })
    }
}
//! Fetching hosted DID documents.
//!
//! Issuer `did.json` documents are published to the document bucket behind
//! the issuers' domains (see `reference/infra/hosted-dids/`). The service
//! reads them through a [`DocumentTransport`], so the same resolver runs
//! against the bucket mirror in development and against fixtures in tests.

use std::collections::HashMap;
use std::path::{Component, Path, PathBuf};

use thiserror::Error;
use url::Url;

#[derive(Debug, Error, PartialEq, Eq)]
pub enum TransportError {
    #[error("invalid document URL {0}")]
    InvalidUrl(String),
    #[error("no document at {0}")]
    NotFound(String),
    #[error("reading {url}: {reason}")]
    Io { url: String, reason: String },
}

/// Something that can GET a document by its HTTPS URL.
pub trait DocumentTransport: Send + Sync {
    fn get(&self, url: &str) -> Result<Vec<u8>, TransportError>;
}

/// Serves `https://<authority>/<path>` from `<root>/<authority>/<path>`: a
/// local mirror of the document bucket, laid out the way the bucket keys
/// its objects.
#[derive(Debug, Clone)]
pub struct MirrorTransport {
    root: PathBuf,
}

impl MirrorTransport {
    pub fn new(root: impl AsRef<Path>) -> Self {
        MirrorTransport { root: root.as_ref().to_path_buf() }
    }

    /// The mirror at `$DID_MIRROR_ROOT`, or the checked-in copy of the bucket.
    pub fn from_env() -> Self {
        match std::env::var_os("DID_MIRROR_ROOT") {
            Some(root) => MirrorTransport::new(root),
            None => MirrorTransport::new(Path::new(env!("CARGO_MANIFEST_DIR")).join("../reference/infra/hosted-dids")),
        }
    }

    fn path_for(&self, url: &str) -> Result<PathBuf, TransportError> {
        let invalid = || TransportError::InvalidUrl(url.to_string());
        let parsed = Url::parse(url).map_err(|_| invalid())?;
        if parsed.scheme() != "https" || url.contains("/../") {
            return Err(invalid());
        }
        let host = parsed.host_str().ok_or_else(invalid)?;
        let authority = match parsed.port() {
            Some(port) => format!("{host}:{port}"),
            None => host.to_string(),
        };
        let mut path = self.root.join(authority);
        for segment in parsed.path_segments().into_iter().flatten() {
            let segment = Path::new(segment);
            if segment.components().any(|c| !matches!(c, Component::Normal(_))) {
                return Err(invalid());
            }
            path.push(segment);
        }
        Ok(path)
    }
}

impl DocumentTransport for MirrorTransport {
    fn get(&self, url: &str) -> Result<Vec<u8>, TransportError> {
        let path = self.path_for(url)?;
        std::fs::read(&path).map_err(|e| match e.kind() {
            std::io::ErrorKind::NotFound => TransportError::NotFound(url.to_string()),
            _ => TransportError::Io { url: url.to_string(), reason: e.to_string() },
        })
    }
}

/// An in-memory set of documents keyed by URL.
#[derive(Debug, Clone, Default)]
pub struct StaticTransport {
    documents: HashMap<String, Vec<u8>>,
}

impl StaticTransport {
    pub fn with(mut self, url: &str, body: impl Into<Vec<u8>>) -> Self {
        self.documents.insert(url.to_string(), body.into());
        self
    }
}

impl DocumentTransport for StaticTransport {
    fn get(&self, url: &str) -> Result<Vec<u8>, TransportError> {
        self.documents.get(url).cloned().ok_or_else(|| TransportError::NotFound(url.to_string()))
    }
}
//! Tenant settings: the in-repo stand-in for the `tenant-settings` table.
//!
//! Every tenant (an onboarded issuer, keyed by its DID) owns a partition of
//! settings, each identified by a key and tagged with a kind. Like the table,
//! a query returns a partition one page at a time in key order, and every
//! page read takes [`PAGE_READ_LATENCY`]. The `tenant-kind` index answers
//! "settings of this kind for this tenant" directly.

use std::collections::{BTreeMap, BTreeSet};
use std::ops::Bound;
use std::sync::Mutex;
use std::time::Duration;

use serde_json::Value;

/// Items returned per page read.
pub const PAGE_SIZE: usize = 100;

/// What one page read costs.
pub const PAGE_READ_LATENCY: Duration = Duration::from_millis(50);

#[derive(Debug, Clone, PartialEq)]
pub struct Setting {
    pub tenant: String,
    pub key: String,
    pub kind: String,
    pub value: Value,
}

impl Setting {
    pub fn new(tenant: &str, key: &str, kind: &str, value: Value) -> Self {
        Setting { tenant: tenant.to_string(), key: key.to_string(), kind: kind.to_string(), value }
    }
}

/// One page of a partition. `next` is the cursor for the following page,
/// `None` on the last one.
#[derive(Debug, Clone, PartialEq)]
pub struct Page {
    pub items: Vec<Setting>,
    pub next: Option<String>,
}

#[derive(Default)]
struct Inner {
    /// tenant → key → setting
    partitions: BTreeMap<String, BTreeMap<String, Setting>>,
    /// (tenant, kind) → keys
    by_kind: BTreeMap<(String, String), BTreeSet<String>>,
}

#[derive(Default)]
pub struct SettingsStore {
    inner: Mutex<Inner>,
}

impl SettingsStore {
    pub fn new() -> Self {
        SettingsStore::default()
    }

    fn lock(&self) -> std::sync::MutexGuard<'_, Inner> {
        self.inner.lock().unwrap_or_else(|poisoned| poisoned.into_inner())
    }

    /// Writes `setting`, replacing any setting with the same tenant and key.
    pub fn put(&self, setting: Setting) {
        let mut inner = self.lock();
        let partition = inner.partitions.entry(setting.tenant.clone()).or_default();
        let previous = partition.insert(setting.key.clone(), setting.clone());
        if let Some(previous) = previous {
            if let Some(keys) = inner.by_kind.get_mut(&(previous.tenant, previous.kind)) {
                keys.remove(&previous.key);
            }
        }
        inner.by_kind.entry((setting.tenant, setting.kind)).or_default().insert(setting.key);
    }

    /// One page of `tenant`'s settings, starting after the key `after`.
    pub async fn query(&self, tenant: &str, after: Option<&str>) -> Page {
        tokio::time::sleep(PAGE_READ_LATENCY).await;
        let inner = self.lock();
        let Some(partition) = inner.partitions.get(tenant) else {
            return Page { items: Vec::new(), next: None };
        };
        let start = match after {
            Some(key) => Bound::Excluded(key.to_string()),
            None => Bound::Unbounded,
        };
        let mut range = partition.range((start, Bound::Unbounded));
        let items: Vec<Setting> = range.by_ref().take(PAGE_SIZE).map(|(_, s)| s.clone()).collect();
        let next = match range.next() {
            Some(_) => items.last().map(|s| s.key.clone()),
            None => None,
        };
        Page { items, next }
    }

    /// `tenant`'s settings of `kind`, through the `tenant-kind` index.
    pub async fn query_kind(&self, tenant: &str, kind: &str) -> Vec<Setting> {
        let items: Vec<Setting> = {
            let inner = self.lock();
            let keys = inner.by_kind.get(&(tenant.to_string(), kind.to_string()));
            let partition = inner.partitions.get(tenant);
            match (keys, partition) {
                (Some(keys), Some(partition)) => keys.iter().filter_map(|k| partition.get(k).cloned()).collect(),
                _ => Vec::new(),
            }
        };
        let pages = items.len().div_ceil(PAGE_SIZE).max(1) as u32;
        tokio::time::sleep(PAGE_READ_LATENCY * pages).await;
        items
    }
}
//! Issuer and verifier service for membership credentials.
//!
//! - [`issuer`] onboards issuers and signs credentials for their members.
//! - [`verifier`] checks the presentations members show at the door.
//! - [`resolver`] turns a DID into its DID document; [`transport`] fetches
//!   the documents that are hosted rather than encoded in the DID.
//! - [`status`] and [`store`] keep issued credentials and their revocation state.
//! - [`notifier`] tells subscribed relying parties when a status changes;
//!   [`settings`] holds the tenants' subscriptions and [`webhook`] sends the
//!   calls.
//! - [`credential`] is the wire format shared by all of the above.

pub mod credential;
pub mod issuer;
pub mod notifier;
pub mod resolver;
pub mod settings;
pub mod status;
pub mod store;
pub mod transport;
pub mod verifier;
pub mod webhook;
# credentials-backend — issuer & verifier service

The service side of the membership system. It signs membership credentials for the clubs and
leagues we've onboarded, and checks the presentations members show at the door.

## How it works

**Issuers.** We identify issuers with `did:key`: an issuer's DID *is* its Ed25519 public key, so
checking an issuer's signature needs nothing but the DID in the credential — no registry lookup,
no network call. An issuer is approved once, at onboarding, and is recorded in
`data/onboarded-issuers.json`.

**Credentials.** A credential is a JSON-LD verifiable credential signed by its issuer
(`Ed25519Signature2020`, over the RFC 8785 canonical form of the credential without its `proof`).
It carries:

| Field | Meaning |
|---|---|
| `issuer` | the issuer's DID |
| `credentialSubject.id` | the member's (holder's) `did:key` |
| `credentialSubject._sd` | salted SHA-256 digests of the claims — never the claims themselves |
| `issued_at`, `not_before` | unix seconds |
| `expirationDate` | unix seconds; the credential is refused after it |
| `credentialStatus` | the issuer's status list and this credential's index in it |
| `proof` | the issuer's signature |

The member receives the credential together with one *disclosure* (`salt`, `name`, `value`) per
claim, and reveals only the claims a door asks for.

**Presentations.** At the door the member's wallet wraps the credential and the chosen disclosures
in a presentation bound to the scanner's `nonce` and `domain`, and signs it with the member's key.
Credentials are single-use: once a credential has been presented at a door it cannot be presented
again.

**Revocation.** Each issuer has a status list — a bitstring with one bit per credential it has
issued. Revoking a credential sets its bit; the verifier refuses any credential whose bit is set.

**Notifications.** Relying parties that don't want to re-read a status list on every check can
subscribe to an issuer's status changes with a webhook; subscriptions are stored as tenant
settings. Status notifications are delivered concurrently to every subscriber, with failed
deliveries retried. A built-in canary subscription receives every change, and the notifier reports
healthy while the canary is acknowledging them.

## Layout

| File | What it does |
|---|---|
| `src/issuer.rs` | onboarding issuers; `Issuer::issue` signs a credential and its disclosures |
| `src/verifier.rs` | `Verifier::verify_presentation` / `verify_credential` |
| `src/resolver.rs` | `Resolver` — DID to DID document |
| `src/transport.rs` | fetching hosted documents (`MirrorTransport`, `StaticTransport`) |
| `src/credential.rs` | wire format: canonical JSON, proofs, disclosures |
| `src/status.rs` | status lists and `revoke_credential` |
| `src/store.rs` | in-memory store: onboarded issuers, issued credentials, status lists |
| `src/notifier.rs` | `Notifier::notify` — status-change webhooks and the canary |
| `src/settings.rs` | tenant settings, including webhook subscriptions |
| `src/webhook.rs` | sending webhook calls (`WebhookTransport`, `HermeticTransport`) |
| `data/onboarded-issuers.json` | the issuers approved to issue through the service |

## Tests

```
cargo test
```

The suite runs offline against fixture keys and documents.
# status-notifier — deployment configuration (production, eu-west-1)
#
# Snapshot of services/status-notifier/deploy.yaml from the platform infrastructure repository.
# Owner: Platform Infrastructure. Applied by the deploy pipeline on merge to main.

service: status-notifier
environment: production
region: eu-west-1

# One invocation per status-change event.
trigger:
  source: credential-status-events      # event bus rule on the issuer service's status stream
  batch_size: 1
  starting_position: latest

function:
  runtime: provided.al2023
  architecture: arm64
  memory_mb: 512
  # Hard limit. The runtime terminates the invocation when it is reached; work still in
  # progress at that point is abandoned.
  timeout_seconds: 10
  reserved_concurrency: 20
  async_invocation:
    maximum_retry_attempts: 0
    maximum_event_age_seconds: 60
    on_failure_destination: none

network:
  egress: public                        # through the shared NAT gateways
  outbound_connect_timeout_ms: 2000

tables:
  tenant-settings:
    partition_key: tenant               # issuer DID
    sort_key: setting_id
    billing_mode: on-demand
    query_page_size: 100                # items returned per Query page
    global_secondary_indexes:
      - name: tenant-kind-index
        partition_key: tenant
        sort_key: kind
        projection: all
    access: read                        # this service never writes settings

logging:
  log_group: /platform/status-notifier
  retention_days: 14
  level: info

monitoring:
  dashboard: status-notifier-overview
  alarms: []

